/* DESIGN D28 section 9: the console's widths (the kernel's own kernel/confont.c, its table generated by
 * tools/mkconfont.py) against the C library's wcwidth (picolibc's own wcwidth.c and tables, compiled here as they are
 * with a stand-in for its locale.h part: the non-CJK locale, as on Zenix) for all 1,114,112 code points: no
 * difference allowed. Run by tools/term-test.sh. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../kernel/kernel.h"
void *kmalloc(u32 n) { return malloc(n); }
#include "../kernel/confont.c"

int pico_wcwidth(wchar_t c);

int main(void)
{
    u32 diff = 0;
    for (u32 c = 0; c <= 0x10FFFF; c++) {
        int k = con_width(c), p = pico_wcwidth((wchar_t)c);
        if (k != p) {
            if (diff++ < 10)
                printf("      U+%04X: the kernel %d, the C library %d\n", c, k, p);
        }
    }
    printf("%s the console's widths are the C library's for all 1,114,112 code points (%u differ)\n",
           diff ? "FAIL:" : "ok:  ", diff);
    if (con_width(0x110000) != -1) {
        printf("FAIL: U+110000 is not a character\n");
        return 1;
    }
    return diff ? 1 : 0;
}
